INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Adventure Time Season 8 Banned Groups', '(?i)^adventure[ ._-]+time[ ._-]+S08.*-(CtrlHD|EPSiLON|H3B|mSD-jT9t|NTb|PRESENT|RTN|SRS|TvR|W4F)\b', NULL, 'Matches releases for season 8 of the show Adventure Time from groups that do not follow the TVDB ordering.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Amazon Prime', '\b(amzn|amazon(hd)?)\b', NULL, 'Amazon Prime Video, or simply Prime Video, is an American subscription video on-demand over-the-top streaming and rental service of Amazon offered both as a stand-alone service and as part of Amazon''s Prime subscription.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Anne of Green Gables Banned Groups', '(?i)^anne[ ._-]+of[ ._-]+green[ ._-]+gables.*-(EGEN)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Apple TV+', '\b(atvp|aptv|Apple TV\+)\b', NULL, 'Apple TV+ is an American subscription OTT streaming service owned and operated by Apple Inc. Launched on November 1, 2019, it offers a selection of original production film and television series called Apple Originals.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Arthur Banned Groups', '(?i)^arthur[ ._-].*-(DAWN)\b', NULL, NULL);
