INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Atmos', '\bATMOS|DDPA(\b|\d)', NULL, '');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('B&W', '(?<=\b[12]\d{3}\b).*\b((B(lack)?[ ._-]?(out|(and|[n&])?[ ._-]?(W(hite)?|Chrome))))\b(?!$)', NULL, 'Black and White colour grading. This regex matches a 4-digit number (optionally surrounded by parentheses), followed by any amount of text, and then detects references to "black and white" in various formats. It supports `blackwhite` (no spaces), `black and white`, `black-white`, "`black & white`, `black/white`, as well as shorthand `BW` and `B&W`, while excluding invalid variations like `b w`, `b-w`, or `b/w`');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('BD3D', '\b(BD3D)\b', NULL, '');
