INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Bluray 3D', '\b(BluRay3D)\b', NULL, '');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Bravia Core', '\b((B)?CORE)\b', NULL, 'Sony Pictures Core (formerly known as Bravia Core) is a video on demand service from Sony for its televisions and smartphones, launched in April 2021. The service offers the streaming of movies at up to 4K resolution provided by Sony Pictures Entertainment. CORE stands for Centre of Real Entertainment.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('CREATiVE24', '\b(CREATiVE24)\b', NULL, NULL);
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Courage the Cowardly Dog Banned Groups', '(?i)^courage[ ._-]+the[ ._-]+cowardly[ ._-]+dog.*-(mSD|Reaperza|ReiDoBregaBR|SKYFiRE)\b', NULL, 'Matches releases for the show Phineas and Ferb from groups that do not follow the TVDB ordering.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Criterion Channel', '\b(CRiT)\b', NULL, 'The Criterion Channel is a subscription-based streaming service launched on April 8, 2019, by The Criterion Collection. Available in the United States and Canada, it features a rich library of films, including Criterion Collection releases with special features, curated playlists, temporarily licensed titles, and original content such as academic overviews and introductions. The Channel also showcases Janus-owned titles not yet available on physical media and maintains a collaborative relationship with Warner Bros. Discovery''s Max platform. Perfect for cinephiles, the service brings a curated cinematic experience to the digital space.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Criterion Group', '^(Criterion)$', NULL, '');
