INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('HBO Max', '\b(hmax|hbom|hbo[ ._-]?max)\b(?=[ ._-]web[ ._-]?(dl|rip)\b)', NULL, 'HBO Max is an American subscription video-on-demand streaming service that offers a range of original programming and content from WarnerMedia''s vast library, encompassing brands such as Warner Bros., CNN, Cartoon Network, TBS, and Turner Classic Movies. In mid-to-late 2023, HBO Max underwent a rebranding to "Max".');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('HBO Max Rename', '\[(HMAX)\b|\b(HMAX)\]', NULL, 'Max, formerly (and in some regions still) known as HBO Max, is an American subscription video on-demand over-the-top streaming service. The platform offers content from the libraries of Warner Bros., Discovery, HBO, CNN, Cartoon Network, Adult Swim, Animal Planet, TBS, TNT, Eurosport, and their related brands.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('HDR', '\b(HDR)\b', NULL, 'This regex matches a `HDR` generalisation. This can be HDR10, HDR10+, etc. ');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('HDR10', '\b(HDR10(?![+]|P(lus)?))', NULL, '');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('HDR10+', '\b(HDR10(?=[+]|P(lus)?))', NULL, '');
