INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Hulu', '\b(hulu)\b', NULL, 'Hulu, an American subscription streaming service owned by Disney, offers recent TV episodes, full seasons of shows, original content, and live TV channels. As of December 2023, Hulu content is being integrated into Disney+, making its library accessible to Disney+ subscribers.');
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('IMAX', '\b((?<!NON[ ._-])IMAX)\b', NULL, 'Matches any IMAX release. This includes:
INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('IMF', '(\b(IMF)\b(?=.*\b(web[ ._-]?rip))\b)', NULL, 'Interoperable Master Format (IMF) is a container format for the standardized digital delivery and storage of finished audio-visual masters, including movies, episodic content and advertisements.');
