INSERT INTO regular_expressions (name, pattern, regex101_id, description) VALUES ('Parks and Recreation NTb Banned', '(?i)^parks[ ._-]+and[ ._-]+recreation.*?\b(web[ ._-]?(dl|\.dl))\b.*?-ntb.*', NULL, 'This is to match the show Parks and Recreation and the release group NTb. This is built out because the NTb release of Parks and Rec is a mislabeled WEBRip and causes a download loop.');
